BEGIN;
CREATE OR REPLACE FUNCTION instrument_lifecycle_reject_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'instrument lifecycle history is immutable'; END $$;
CREATE TABLE IF NOT EXISTS instrument_assets (asset_hash text PRIMARY KEY CHECK(asset_hash ~ '^[a-f0-9]{64}$'), asset_id text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS instrument_native_identities (identity_hash text PRIMARY KEY CHECK(identity_hash ~ '^[a-f0-9]{64}$'), tenant_id text NOT NULL, venue text NOT NULL, environment text NOT NULL, namespace text NOT NULL, native_id text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,venue,environment,namespace,native_id));
CREATE TABLE IF NOT EXISTS instrument_definition_versions (definition_hash text PRIMARY KEY CHECK(definition_hash ~ '^[a-f0-9]{64}$'), tenant_id text NOT NULL, stable_id text NOT NULL, version integer NOT NULL CHECK(version > 0), identity_hash text NOT NULL REFERENCES instrument_native_identities(identity_hash), status text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,stable_id,version));
CREATE TABLE IF NOT EXISTS instrument_aliases (alias_hash text PRIMARY KEY CHECK(alias_hash ~ '^[a-f0-9]{64}$'), tenant_id text NOT NULL, scope_key text NOT NULL, alias text NOT NULL, definition_hash text NOT NULL REFERENCES instrument_definition_versions(definition_hash), valid_until timestamptz NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS instrument_lifecycle_events (event_hash text PRIMARY KEY CHECK(event_hash ~ '^[a-f0-9]{64}$'), tenant_id text NOT NULL, scope_key text NOT NULL, event_id text NOT NULL, native_sequence bigint NOT NULL CHECK(native_sequence >= 0), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,scope_key,event_id));
CREATE TABLE IF NOT EXISTS instrument_continuity_transforms (transform_hash text PRIMARY KEY CHECK(transform_hash ~ '^[a-f0-9]{64}$'), tenant_id text NOT NULL, old_definition_hash text NOT NULL, new_definition_hash text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS instrument_registry_snapshots (snapshot_hash text PRIMARY KEY CHECK(snapshot_hash ~ '^[a-f0-9]{64}$'), tenant_id text NOT NULL, event_watermark bigint NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS instrument_operation_decisions (decision_hash text PRIMARY KEY CHECK(decision_hash ~ '^[a-f0-9]{64}$'), tenant_id text NOT NULL, scope_key text NOT NULL, operation text NOT NULL, outcome text NOT NULL CHECK(outcome IN ('allow','block','unknown','safe_only')), idempotency_key text NOT NULL, expires_at timestamptz NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,scope_key,idempotency_key));
CREATE TABLE IF NOT EXISTS instrument_rebaseline_plans (plan_hash text PRIMARY KEY CHECK(plan_hash ~ '^[a-f0-9]{64}$'), tenant_id text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS instrument_rebaseline_receipts (receipt_hash text PRIMARY KEY CHECK(receipt_hash ~ '^[a-f0-9]{64}$'), tenant_id text NOT NULL, plan_hash text NOT NULL REFERENCES instrument_rebaseline_plans(plan_hash), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS instrument_projection_transitions (transition_hash text PRIMARY KEY CHECK(transition_hash ~ '^[a-f0-9]{64}$'), tenant_id text NOT NULL, scope_key text NOT NULL, predecessor_hash text, watermark bigint NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
DO $$ DECLARE item text; BEGIN FOREACH item IN ARRAY ARRAY['instrument_assets','instrument_native_identities','instrument_definition_versions','instrument_aliases','instrument_lifecycle_events','instrument_continuity_transforms','instrument_registry_snapshots','instrument_operation_decisions','instrument_rebaseline_plans','instrument_rebaseline_receipts','instrument_projection_transitions'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS %I_immutable ON %I',item,item); EXECUTE format('CREATE TRIGGER %I_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION instrument_lifecycle_reject_mutation()',item,item); END LOOP; END $$;
COMMIT;
